static BOOL capture(HWND w,DWORD *out,int width,int height){HDC dc=CreateCompatibleDC(NULL);BITMAPINFO bi={0};void *bits=NULL;bi.bmiHeader.biSize=sizeof(bi.bmiHeader);bi.bmiHeader.biWidth=width;bi.bmiHeader.biHeight=-height;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;HBITMAP b=CreateDIBSection(dc,&bi,DIB_RGB_COLORS,&bits,NULL,0);HGDIOBJ old=b?SelectObject(dc,b):NULL;if(!old)return FALSE;memset(bits,0x55,(size_t)width*height*4);SendMessageW(w,WM_PRINTCLIENT,(WPARAM)dc,PRF_CLIENT);GdiFlush();memcpy(out,bits,(size_t)width*height*4);SelectObject(dc,old);DeleteObject(b);DeleteDC(dc);return TRUE;}
