static int run(int argc,WCHAR **argv){CHECK(argc==2);INITCOMMONCONTROLSEX ic={sizeof(ic),ICC_STANDARD_CLASSES};CHECK(InitCommonControlsEx(&ic));HMODULE dll=GetModuleHandleW(sizeof(void*)==8?L"ntw16s64.dll":L"ntw16s32.dll"),f=LoadLibraryW(argv[1]);CHECK(dll&&f);window_fn attached=(void*)GetProcAddress(dll,"Ntw16sWindowAttached"),remove=(void*)GetProcAddress(dll,"Ntw16sWindowRemove");reg_fn reg=(void*)GetProcAddress(f,"FixtureRegister"),unreg=(void*)GetProcAddress(f,"FixtureUnregister");create_fn create=(void*)GetProcAddress(f,"FixtureCreate");CHECK(attached&&remove&&reg&&unreg&&create&&reg());HWND root=CreateWindowW(L"STATIC",L"",WS_OVERLAPPEDWINDOW,10,10,300,200,NULL,NULL,GetModuleHandleW(NULL),NULL);CHECK(root);ShowWindow(root,SW_SHOWNA);for(int mode=0;mode<3;mode++){HWND g=create(root,mode==2,mode!=0);CHECK(g);CHECK(RedrawWindow(g,NULL,NULL,RDW_INVALIDATE|RDW_FRAME|RDW_UPDATENOW));if(!mode)CHECK(!attached(g));else{CHECK(attached(g));RECT r;CHECK(GetClientRect(g,&r));int w=r.right,h=r.bottom;CHECK(w>60&&w<=220&&h>60&&h<=120);DWORD before[220*120],after[220*120];CHECK(capture(g,before,w,h));SCROLLINFO i={.cbSize=sizeof(i),.fMask=SIF_ALL};CHECK(GetScrollInfo(g,SB_HORZ,&i)&&i.nMax==100);SendMessageW(g,WM_HSCROLL,SB_LINERIGHT,0);CHECK(GetScrollInfo(g,SB_HORZ,&i)&&i.nPos==1);SendMessageW(g,WM_HSCROLL,SB_LINELEFT,0);CHECK(GetScrollInfo(g,SB_HORZ,&i)&&i.nPos==0);CHECK(GetScrollInfo(g,SB_VERT,&i)&&i.nMax==100);SendMessageW(g,WM_VSCROLL,SB_LINEDOWN,0);CHECK(GetScrollInfo(g,SB_VERT,&i)&&i.nPos==1);SendMessageW(g,WM_VSCROLL,SB_LINEUP,0);CHECK(GetScrollInfo(g,SB_VERT,&i)&&i.nPos==0);if(mode==1)CHECK(remove(g));else{HWND other=CreateWindowW(L"STATIC",L"",WS_CHILD|WS_VISIBLE,0,0,250,150,root,NULL,GetModuleHandleW(NULL),NULL);CHECK(other);CHECK(SetParent(g,other)==root);CHECK(RedrawWindow(g,NULL,NULL,RDW_INVALIDATE|RDW_FRAME|RDW_UPDATENOW));CHECK(!attached(g));CHECK(SetParent(g,root)==other);CHECK(DestroyWindow(other));}CHECK(!attached(g));CHECK(capture(g,after,w,h));CHECK(!memcmp(before,after,(size_t)w*h*4));}CHECK(DestroyWindow(g));}CHECK(small_tests(f,root,attached,remove)==0);CHECK(DestroyWindow(root));CHECK(unreg());CHECK(FreeLibrary(f));printf("VCL_GRID_MODULE_OK bits=%u invalid=1 both=1 scroll=1 vertical=1 client=1 removal=1 reparent=1 small=1 transition=1 pixels=1 cleanup=1\n",(unsigned)sizeof(void*)*8);return 0;}
int wmain(int argc,WCHAR **argv){return isolated_process(argc,argv,run);}
